toolArgs.file_text:
@page "/settings"
@namespace sv_ce45bd79199940ea80ea67ffe28d300c.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: 100vh;
    gap: 0;
}

/* Sidebar */
::deep .settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    text-align: left;
    width: 100%;
    transition: background-color 0.15s, color 0.15s;
}

::deep .sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

::deep .sidebar-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

::deep .sidebar-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

/* Shared section styles */
::deep .settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #444;
}

::deep .form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

::deep .form-control:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

::deep .button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: opacity 0.15s;
}

::deep .btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-primary {
    background: #0d6efd;
    color: #fff;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .btn-secondary {
    background: #6c757d;
    color: #fff;
}

::deep .btn-secondary:hover:not(:disabled) {
    background: #5c636a;
}

::deep .btn-danger {
    background: #dc3545;
    color: #fff;
}

::deep .btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

::deep .btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast messages */
::deep .toast-message {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

::deep .toast-message.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

::deep .toast-message.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Toggle items */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

::deep .toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

::deep .toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
}

/* Channel list */
::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
    padding-left: 0.5rem;
}

/* Avatar */
::deep .avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

::deep .avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
}

::deep .avatar-url {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
}

/* Expandable panel */
::deep .expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

::deep .panel-content {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* Two-factor */
::deep .two-factor-section {
    margin-bottom: 1.5rem;
}

::deep .status-row {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

::deep .status-indicator {
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
    font-size: 0.85rem;
    font-weight: 500;
}

::deep .status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

::deep .status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
}

::deep .info-text {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #666;
}

/* Sessions table */
::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.85rem;
    color: #555;
}

::deep .current-badge {
    font-size: 0.8rem;
    color: #0f5132;
    background: #d1e7dd;
    padding: 0.2rem 0.5rem;
    border-radius: 8px;
}

/* Modal */
::deep .modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .modal-dialog {
    background: #fff;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2);
}

::deep .modal-dialog h4 {
    margin-bottom: 0.75rem;
}

/* Radio groups */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

::deep .radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Preview area */
::deep .preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 2px dashed #ccc;
    border-radius: 8px;
    transition: all 0.2s;
}

::deep .preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #555;
}

::deep .preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

::deep .preview-area.theme-system {
    background: #f8f9fa;
    color: #333;
}

::deep .preview-area.font-small {
    font-size: 0.8rem;
}

::deep .preview-area.font-medium {
    font-size: 1rem;
}

::deep .preview-area.font-large {
    font-size: 1.2rem;
}

::deep .preview-area.compact {
    padding: 0.75rem;
    line-height: 1.2;
}

